import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type GrowthChartProps = Record<string, any>;

const GrowthChart: React.FC<GrowthChartProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 4,
  trendColor = "#FFC000",
  trendOutlineColor = "#000000",
  chartElementsColor = "#000000",
}) => {

  {/* Load Google Fonts (Included for standard structure, though not used in pure shapes) */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Constraints
  const w = width;
  const h = height;
  const s = Math.min(w, h) / 1080;

  // Chart Base Sizing
  const bodyWidth = w * 0.073;
  const headSize = w * 0.057;
  const gap = h * 0.018;
  const baseY = h * 0.907;

  // Data mapping representing relative heights and X-positions
  const relData = [
    { height: 0.111, x: 0.1875 },
    { height: 0.166, x: 0.3125 },
    { height: 0.259, x: 0.4375 },
    { height: 0.370, x: 0.5625 },
    { height: 0.481, x: 0.6875 },
    { height: 0.601, x: 0.8125 },
  ];

  // Path coordinates tracking above the chart elements
  const relArrowPoints = [
    { x: 0.1875, y: 0.648 },
    { x: 0.3125, y: 0.416 },
    { x: 0.4375, y: 0.509 },
    { x: 0.5625, y: 0.231 },
    { x: 0.6875, y: 0.324 },
    { x: 0.8125, y: 0.138 }
  ];

  // SVG Path Construction
  const pathData = `M ${relArrowPoints.map(p => `${p.x * w} ${p.y * h}`).join(' L ')}`;
  const endX = relArrowPoints[5].x * w;
  const endY = relArrowPoints[5].y * h;
  const p5X = relArrowPoints[4].x * w;
  const p5Y = relArrowPoints[4].y * h;
  
  // Calculate final arrow tip rotation
  const dx = endX - p5X;
  const dy = endY - p5Y;
  const angle = Math.atan2(dy, dx) * (180 / Math.PI);

  // Arrowhead polygon shape (Scaled to match responsiveness)
  const p1 = `${-60 * s},${-90 * s}`;
  const p2 = `${150 * s},0`;
  const p3 = `${-60 * s},${90 * s}`;
  const polygonPoints = `${p1} ${p2} ${p3}`;

  // Unified Outline Stroke Thickness Trick
  const outlineStroke = 60 * s;
  const fillStroke = 36 * s;

  // Draw Animation Progress
  const clipWidth = interpolate(frame, [15, 85], [0, w], {
    extrapolateRight: 'clamp',
    extrapolateLeft: 'clamp',
    easing: Easing.out(Easing.cubic)
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* People / Chart Base Layer */}
      {relData.map((item, index) => {
        const delay = index * 6; // Stagger effect
        
        const bodyScaleY = spring({
          frame: frame - delay,
          fps,
          config: { damping: 14, mass: 0.8 },
        });
        
        const headScale = spring({
          frame: frame - delay - 3,
          fps,
          config: { damping: 12, mass: 0.6 },
        });

        const targetHeight = item.height * h;
        const currentHeight = Math.max(0, bodyScaleY * targetHeight);
        const xPos = item.x * w;

        return (
          <React.Fragment key={index}>
            <div style={{
              position: 'absolute',
              left: xPos - bodyWidth / 2,
              bottom: h - baseY,
              width: bodyWidth,
              height: currentHeight,
              backgroundColor: chartElementsColor,
              borderTopLeftRadius: bodyWidth / 2,
              borderTopRightRadius: bodyWidth / 2,
              transformOrigin: 'bottom center',
              transition: 'none',
            }} />
            
            <div style={{
              position: 'absolute',
              left: xPos - headSize / 2,
              bottom: h - baseY + currentHeight + gap,
              width: headSize,
              height: headSize,
              borderRadius: '50%',
              backgroundColor: chartElementsColor,
              transform: `scale(${headScale})`,
              transition: 'none',
            }} />
          </React.Fragment>
        )
      })}

      {/* Growing Trend Arrow Layer */}
      <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none' }}>
        <defs>
          <clipPath id="arrow-clip">
            <rect x="0" y="0" width={clipWidth} height={h} />
          </clipPath>
        </defs>

        <g clipPath="url(#arrow-clip)">
          {/* Outline Layer (Thick stroke renders first) */}
          <g stroke={trendOutlineColor} strokeWidth={outlineStroke} strokeLinejoin="round" strokeLinecap="round">
            <path d={pathData} fill="none" />
            <g transform={`translate(${endX}, ${endY}) rotate(${angle})`}>
              <polygon points={polygonPoints} fill={trendOutlineColor} />
            </g>
          </g>

          {/* Fill Layer (Inner stroke overlaps perfectly for a seamless border) */}
          <g stroke={trendColor} strokeWidth={fillStroke} strokeLinejoin="round" strokeLinecap="round">
            <path d={pathData} fill="none" />
            <g transform={`translate(${endX}, ${endY}) rotate(${angle})`}>
              <polygon points={polygonPoints} fill={trendColor} />
            </g>
          </g>
        </g>
      </svg>

    </AbsoluteFill>
  );
};

export default GrowthChart;